struct translation_key {
    const char *id = nullptr;

    constexpr translation_key() = default;
    constexpr explicit translation_key(const char *key) : id(key) {}
    constexpr operator bool() const { return id && *id; }
    constexpr bool operator==(translation_key other) const { return id == other.id; }
    constexpr bool operator!=(translation_key other) const { return id != other.id; }
};

